// Serves the Baat Chat home-screen icon.
// The iPhone fetches this when you tap Share > Add to Home Screen.
// The image is stored inside this file, so no separate image upload is needed.
const ICON = "";

export default async () =>
  new Response(Buffer.from(ICON, "base64"), {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": "public, max-age=86400",
    },
  });
